<?php defined('BASEPATH') or exit('No direct script access allowed'); $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); $statement=$native_statement??['from'=>'2000-01-01','to'=>'2100-12-31','rows'=>[],'contacts'=>[]]; ?>
<h4 class="customer-profile-group-heading">Extrato financeiro</h4>
<form method="get" action="<?= e(admin_url('clients/client/'.$client->userid)); ?>" class="row"><input type="hidden" name="group" value="statement"><div class="col-md-3"><label>De</label><input class="form-control" type="date" name="from" value="<?= $e($statement['from']); ?>"></div><div class="col-md-3"><label>Até</label><input class="form-control" type="date" name="to" value="<?= $e($statement['to']); ?>"></div><div class="col-md-3 tw-mt-6"><button class="btn btn-primary" type="submit">Atualizar extrato</button></div></form>
<div class="tw-mt-4"><a class="btn btn-default" target="_blank" href="<?= e(admin_url('clients/statement_pdf?customer_id='.$client->userid.'&from='.rawurlencode($statement['from']).'&to='.rawurlencode($statement['to']))); ?>">PDF</a></div>
<div class="table-responsive tw-mt-4"><table class="table"><thead><tr><th>Fatura</th><th>Emissão</th><th>Vencimento</th><th>Status</th><th>Total</th></tr></thead><tbody><?php $sum=0;foreach($statement['rows'] as$row){$sum+=(float)$row['total']; ?><tr><td><?= $e($row['formatted_number']); ?></td><td><?= $e($row['date']); ?></td><td><?= $e($row['duedate']); ?></td><td><?= $e($row['status']); ?></td><td><?= $e($row['currency'].' '.$row['total']); ?></td></tr><?php } ?><?php if(empty($statement['rows'])){ ?><tr><td colspan="5">Nenhuma fatura no período.</td></tr><?php } ?></tbody><tfoot><tr><th colspan="4" class="text-right">Total</th><th><?= $e(number_format($sum,2,'.','')); ?></th></tr></tfoot></table></div>
<?php if(!empty($statement['contacts'])){ echo form_open(admin_url('clients/send_statement?customer_id='.$client->userid.'&from='.rawurlencode($statement['from']).'&to='.rawurlencode($statement['to']))); echo form_hidden('_company_context',CompanyRequestScope::context()->token()); echo form_hidden('_native_company_csrf',$company_clients_csrf); echo form_hidden('request_key',bin2hex(random_bytes(32))); ?><div class="form-group"><label>Enviar para</label><?php foreach($statement['contacts'] as$contact){ ?><label class="checkbox-inline"><input type="checkbox" name="send_to[]" value="<?= $e($contact['id']); ?>"> <?= $e(trim($contact['firstname'].' '.$contact['lastname']).' ('.$contact['email'].')'); ?></label><?php } ?></div><input class="form-control" name="cc" placeholder="CC"><button class="btn btn-primary tw-mt-2" type="submit">Enviar extrato</button><?php echo form_close(); } ?>
